<?php
require_once __DIR__.'/includes/bootstrap.php'; require_auth(); if(role()!=='admin'){http_response_code(403);exit('Accès réservé à l’administrateur.');}
$page_title='Maintenance & équipements';$pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$a=$_POST['action']??'';if($a==='equipment'){ $d=trim($_POST['designation']??'');if($d==='')throw new Exception('La désignation est obligatoire.');$s=$pdo->prepare('INSERT INTO equipements(designation,date_acquisition,etat,fournisseur_id) VALUES(?,?,?,?)');$s->execute([$d,$_POST['date_acquisition']?:null,$_POST['etat']??'en_service',($_POST['fournisseur_id']??'')?:null]);flash('Équipement ajouté.');}
 elseif($a==='intervention'){ $eq=(int)$_POST['equipment_id'];$type=trim($_POST['type']??'');$cost=(float)($_POST['cout']??0);$duration=(int)($_POST['duree_arret']??0);if(!$eq||$type===''||$cost<0||$duration<0)throw new Exception('Données d’intervention invalides.');$pdo->beginTransaction();$s=$pdo->prepare('INSERT INTO interventions(equipement_id,type,date_intervention,duree_arret_min,cout) VALUES(?,?,?,?,?)');$s->execute([$eq,$type,$_POST['date_intervention']?:date('Y-m-d'),$duration,$cost]);if(!empty($_POST['en_panne'])){$pdo->prepare("UPDATE equipements SET etat='en_panne' WHERE id=?")->execute([$eq]);}$pdo->commit();flash('Intervention enregistrée.');}
 elseif($a==='state'){ $state=$_POST['etat']??'';if(!in_array($state,['en_service','en_panne','hors_service'],true))throw new Exception('État incorrect.');$pdo->prepare('UPDATE equipements SET etat=? WHERE id=?')->execute([$state,(int)$_POST['id']]);flash('État de l’équipement mis à jour.');}
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash($e->getMessage(),'error');}redirect('maintenance.php');}
$sup=$pdo->query('SELECT id,nom FROM fournisseurs ORDER BY nom')->fetchAll();$eqs=$pdo->query('SELECT e.*,s.nom fournisseur FROM equipements e LEFT JOIN fournisseurs s ON s.id=e.fournisseur_id ORDER BY e.designation')->fetchAll();$inter=$pdo->query('SELECT i.*,i.duree_arret_min AS duree_arret,e.designation FROM interventions i JOIN equipements e ON e.id=i.equipement_id ORDER BY i.id DESC LIMIT 50')->fetchAll();require 'includes/header.php';?>
<div class="panel"><h2>Ajouter un équipement</h2><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="equipment"><div class="field"><label>Désignation</label><input name="designation" required placeholder="Machine à laver 12 kg"></div><div class="field"><label>Date d'acquisition</label><input type="date" name="date_acquisition"></div><div class="field"><label>État</label><select name="etat"><option value="en_service">En service</option><option value="en_panne">En panne</option><option value="hors_service">Hors service</option></select></div><div class="field"><label>Fournisseur (facultatif)</label><select name="fournisseur_id"><option value="">Non renseigné</option><?php foreach($sup as $s):?><option value="<?=$s['id']?>"><?=e($s['nom'])?></option><?php endforeach;?></select></div><div class="field full"><button class="btn">Ajouter l'équipement</button></div></form></div>
<div class="panel"><h2>Déclarer une intervention / maintenance</h2><?php if(!$eqs):?><p class="notice">Ajoutez d'abord un équipement.</p><?php else:?><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="intervention"><div class="field"><label>Équipement</label><select name="equipment_id"><?php foreach($eqs as $x):?><option value="<?=$x['id']?>"><?=e($x['designation'])?></option><?php endforeach;?></select></div><div class="field"><label>Nature de l'intervention</label><select name="type" required><option value="preventive">Préventive</option><option value="corrective">Réparation</option><option value="nettoyage">Nettoyage / détartrage</option><option value="autre">Autre</option></select></div><div class="field"><label>Date</label><input type="date" name="date_intervention" value="<?=date('Y-m-d')?>" required></div><div class="field"><label>Durée d'arrêt (minutes)</label><input type="number" min="0" name="duree_arret" value="0"></div><div class="field"><label>Coût (FCFA)</label><input type="number" min="0" step="1" name="cout" value="0"></div><div class="field"><label><input type="checkbox" name="en_panne" value="1" style="width:auto"> Marquer l'équipement en panne</label></div><div class="field full"><button class="btn green">Enregistrer l'intervention</button></div></form><?php endif;?></div>
<div class="panel"><h2>Parc des équipements</h2><div class="table-wrap"><table><thead><tr><th>Équipement</th><th>Acquisition</th><th>Fournisseur</th><th>État</th><th>Modifier l'état</th></tr></thead><tbody><?php foreach($eqs as $x):?><tr><td><b><?=e($x['designation'])?></b></td><td><?=e($x['date_acquisition']??'—')?></td><td><?=e($x['fournisseur']??'—')?></td><td><?=e(str_replace('_',' ',$x['etat']))?></td><td><form method="post" class="actions"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="action" value="state"><input type="hidden" name="id" value="<?=$x['id']?>"><select name="etat"><option value="en_service" <?=$x['etat']==='en_service'?'selected':''?>>En service</option><option value="en_panne" <?=$x['etat']==='en_panne'?'selected':''?>>En panne</option><option value="hors_service" <?=$x['etat']==='hors_service'?'selected':''?>>Hors service</option></select><button class="btn small">OK</button></form></td></tr><?php endforeach;?><?php if(!$eqs):?><tr><td colspan="5" class="empty">Aucun équipement enregistré.</td></tr><?php endif;?></tbody></table></div></div>
<div class="panel"><h2>Historique des interventions</h2><div class="table-wrap"><table><thead><tr><th>Date</th><th>Équipement</th><th>Intervention</th><th>Arrêt</th><th>Coût</th></tr></thead><tbody><?php foreach($inter as $i):?><tr><td><?=e($i['date_intervention'])?></td><td><?=e($i['designation'])?></td><td><?=e($i['type'])?></td><td><?=e($i['duree_arret'])?> min</td><td><?=money($i['cout'])?></td></tr><?php endforeach;?><?php if(!$inter):?><tr><td colspan="5" class="empty">Aucune intervention enregistrée.</td></tr><?php endif;?></tbody></table></div></div><?php require 'includes/footer.php';?>